<?php require_once __DIR__.'/../bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM anime WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Anime not found');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$pdo->prepare('UPDATE anime SET title=?,english_title=?,japanese_title=?,synopsis=?,poster=?,banner=?,trailer_url=?,type=?,status=?,episodes=?,year=?,season=?,score=? WHERE id=?');$q->execute([trim($_POST['title']),trim($_POST['english_title']),trim($_POST['japanese_title']),trim($_POST['synopsis']),trim($_POST['poster']),trim($_POST['banner']),trim($_POST['trailer_url']),trim($_POST['type']),trim($_POST['status']),($_POST['episodes']?:null),($_POST['year']?:null),trim($_POST['season']),($_POST['score']?:null),$id]);header('Location: anime.php');exit;}$title='Edit anime — AniRead';include __DIR__.'/../includes/header.php';?><h1>Edit anime</h1><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php foreach(['title','english_title','japanese_title','poster','banner','trailer_url','type','status','year','season','score','episodes'] as $f):?><label><?=ucwords(str_replace('_',' ',$f))?></label><input class="input" name="<?=$f?>" value="<?=e($a[$f])?>" <?=in_array($f,['title'])?'required':''?>><?php endforeach;?><label>Synopsis</label><textarea name="synopsis" rows="7"><?=e($a['synopsis'])?></textarea><br><button class="btn">Save</button></form><?php include __DIR__.'/../includes/footer.php';
